SELECT table_name, engine, table_collation FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('bot_principals','bot_credentials','bot_scopes','bot_audit_events') ORDER BY table_name;
SELECT table_name, column_name, column_type, is_nullable, column_default, extra FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('bot_principals','bot_credentials','bot_scopes','bot_audit_events') ORDER BY table_name, ordinal_position;
SELECT table_name, index_name, non_unique, GROUP_CONCAT(column_name ORDER BY seq_in_index) AS indexed_columns FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('bot_principals','bot_credentials','bot_scopes','bot_audit_events') GROUP BY table_name, index_name, non_unique ORDER BY table_name, index_name;
SELECT table_name, constraint_name, constraint_type FROM information_schema.table_constraints WHERE constraint_schema=DATABASE() AND table_name IN ('bot_principals','bot_credentials','bot_scopes','bot_audit_events') ORDER BY table_name, constraint_name;
SELECT constraint_name, check_clause FROM information_schema.check_constraints WHERE constraint_schema=DATABASE() AND constraint_name LIKE 'CK_bot_%' ORDER BY constraint_name;
